<?php require __DIR__.'/includes/core.php';try{$exists=(int)one("SELECT COUNT(*) n FROM users WHERE role='admin'")['n'];}catch(Throwable $e){http_response_code(500);exit('Database connection failed. Import database/install.sql and update includes/config.php.');}if($exists){http_response_code(403);exit('Setup is locked because an administrator already exists.');}$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$phone=phone($_POST['phone']??'');$pass=$_POST['password']??'';if(strlen($name)<3||!preg_match('/^0[0-9]{10}$/',$phone)||strlen($pass)<12)$msg='Enter a name, valid Nigerian phone number, and password of at least 12 characters.';else{sql("INSERT INTO users(name,phone,password_hash,role,must_change_password) VALUES (?,?,?,'admin',0)",[$name,$phone,password_hash($pass,PASSWORD_DEFAULT)]);audit('initial_setup','Administrator created');go('login.php');}}ob_start();?><div class="card"><p>Create the first administrator. This page automatically locks after creation.</p><?php if($msg)echo '<div class="alert error">'.h($msg).'</div>';?><form method="post"><?=token()?><label>Administrator name</label><input name="name" required><label>Phone (login)</label><input name="phone" required placeholder="08012345678"><label>Strong password (12+ characters)</label><input type="password" name="password" required minlength="12"><p><button>Create administrator</button></p></form></div><?php layout('First-time setup',ob_get_clean());